for (key, new) in update {
    match (doc.get_mut(key), new) {
        (Some(Value::Array(old)), Value::Array(items))
            if (keyed(old) || old.is_empty()) && keyed(items) =>
        {
            for item in items {
                let id = id_of(item);
                match old.iter_mut().find(|o| id_of(o) == id) {
                    Some(slot) => *slot = item.clone(),
                    None => old.push(item.clone()),
                }
            }
            old.sort_by(|a, b| {
                natural_cmp(&id_of(a).unwrap_or_default(), &id_of(b).unwrap_or_default())
            });
        }
        _ => {
            doc.insert(key.clone(), new.clone());
        }
    }
}

let value = match (input.get("document"), input.get("update")) {
    (Some(d), None) if remove.is_empty() => d.clone(),
    (Some(_), _) => {
        return ToolOutput::err(
            "Send either `document` (the whole document) or `update` with `remove`, not both.",
        );
    }
    (None, update) => {
        let existing = doc::load(&md);
        if existing.is_none() && !remove.is_empty() {
            return ToolOutput::err(format!(
                "There is no {} at {} yet, so there is nothing to remove.",
                kind.label(),
                md.display()
            ));
        }
        let empty = Value::Object(Default::default());
        match doc::apply_update(existing, update.unwrap_or(&empty), &remove) {
            Ok(v) => v,
            Err(e) => return ToolOutput::err(e.0),
        }
    }
};

