export function outlineOf(doc: Document): Outline {
  switch (doc.kind) {
    case "research":
      return researchOutline(doc.doc);
    case "spec":
      return specOutline(doc.doc);
    case "plan":
      return planOutline(doc.doc);
    case "phase":
      return phaseOutline(doc.doc);
  }
}

